    "relative_velocity": "सापेक्ष वेग",
    "two_things_moving_each": "दो गतिमान वस्तुएँ, हर एक किसी वेग और दिशा में: एक, दूसरी से देखने पर, कितनी तेज़ और किस ओर जाती है, चित्र सहित। या चौड़ाई d की नदी पार करती नाव, पानी के सापेक्ष वेग v पर, धारा u: सीधे पार की ओर रखने पर, कितना समय लगता है और यह कितनी नीचे पहुँचती है; और धारा के विपरीत वह दिशा जो इसे सीधे पार ले जाए। दिशाएँ पूर्व से, वामावर्त, उपयोग में चल रही इकाई में।",
