    "punnett_squares_of_up": "छह जीनों तक के पनेट वर्ग, चित्रित, और X के; हार्डी–वाइनबर्ग, p से, गिनतियों से उनके χ² परीक्षण के साथ, या अप्रभावी लक्षण से; संकरण का χ²; दो या तीन जीनों के जीन मानचित्र, गुणसूत्र चित्रित; संतानों की प्रायिकताएँ; प्रजनक के समीकरण से वंशागतित्व; एपिस्टैसिस और कौन सा अनुपात बैठता है; आनुवंशिक जोखिम, परिवार वंशवृक्ष के रूप में चित्रित; और रक्त समूह।",
