    "appearance": "रूप",
    "what_looks_like_pure": "शुद्ध रूप में, कमरे के तापमान पर यह कैसा दिखता है।",
    "light_of_atoms_as": "इसके परमाणुओं का प्रकाश, गैस के रूप में, 380 nm के बैंगनी से 750 के लाल तक: अवशोषण, इससे होकर चमकाया गया सफ़ेद प्रकाश, इंद्रधनुष के आर-पार काली रेखाएँ जहाँ यह रंग निकाल लेता है; उत्सर्जन, गर्म किए जाने पर या चिंगारी में, वही रंग अकेले, काले पर चमकीले। हर तत्व की अपनी रेखाएँ होती हैं, उँगलियों के निशान की तरह: इसीलिए हीलियम पृथ्वी से पहले सूर्य में मिला। इसकी सबसे प्रबल रेखाएँ, जैसे NIST सूचीबद्ध करता है, जितनी प्रबल उतनी चौड़ी; जिस तत्व के परमाणु की यहाँ कोई नहीं, उसके आयन की। क्लिक करें: दूसरी वाली।",
    "alkali_metal": "क्षार धातु",
    "group_1_but_hydrogen": "हाइड्रोजन को छोड़कर समूह 1: नरम धातुएँ जो पानी से तीव्र अभिक्रिया करती हैं, हाइड्रॉक्साइड और हाइड्रोजन देती हुई। एक बाहरी इलेक्ट्रॉन, 1+ आयन के रूप में खोया जाता है।",
    "alkaline_earth_metal": "क्षारीय मृदा धातु",
