    "actinium_to_lawrencium_filling": "एक्टिनियम से लॉरेंशियम, 5f उपकोश भरते हुए: सब रेडियोधर्मी; केवल थोरियम और यूरेनियम प्रकृति में आम हैं।",
    "draws_up_to_25": "x के 25 फ़ंक्शन तक बनाता है, किसी और अक्षर के लिए स्लाइडर के साथ, जैसे a x^2 + b में a: x^2 – 3, 2sin(x); अनुक्रम, a(n) = a(n – 1) + 2 {a(1) = 1}; और ढलान क्षेत्र, dy/dx = x – y {y(0) = 1}, क्लिक करने से एक हल जुड़ता है। मूल, उच्चतम, निम्नतम और प्रतिच्छेद चिह्नित करता है। खिसकाने के लिए खींचें, ज़ूम के लिए स्क्रॉल या पिंच करें; किसी वक्र के मानों के लिए उस पर पॉइंटर ले जाएँ, उसकी स्पर्श रेखा के लिए क्लिक करें। तालिका टैब इन्हें सूचीबद्ध करता है।",
