    "zoom_in": "ज़ूम इन",
    "twice_as_close_about": "मध्य के आस-पास दोगुना पास। पहिया जहाँ पॉइंटर है उसके आस-पास ज़ूम करता है, उसे मध्य की ओर लाते हुए; पिंच जहाँ है वहाँ के आस-पास ज़ूम करता है।",
