    "graph_fills_page_to": "ग्राफ़ पेज भर देता है, वक्रों का ज़्यादा देखने के लिए: वेबसाइट पर पूरी विंडो, और एक्सटेंशन में कैलकुलेटर के बगल में अपनी अलग विंडो में।",
