    "copy_link_opens_graph": "ऐसा लिंक कॉपी करें जो इस ग्राफ़, इसके वक्र, स्लाइडर, दृश्य और सेटिंग खोलता है, किसी के भी लिए; इसे चित्र के रूप में कॉपी करें, या PNG या SVG के रूप में सहेजें, हर वक्र के फ़ंक्शन के साथ; या इसकी तालिका CSV के रूप में सहेजें। यही सब ग्राफ़ पर राइट-क्लिक से भी।",
