    "before_number_27_3": "संख्या से पहले: ∛ 27 = 3, जैसे 3 <sup>x</sup>√y 27; यह x<sup>3</sup> को पलटता है। ऋणात्मक संख्याएँ चलती हैं: ∛ –8 = –2। Enter, → या Tab इसे बंद करता है; = हल करता है।",
    "root_first_then_number": "पहले मूल, फिर संख्या, जैसा लिखा जाता है: 4 <sup>x</sup>√y 81 = 3, 81 का चौथा मूल। पहले दबाने पर, दो खाली बॉक्स वाला मूल आता है: मूल टाइप करें, Enter अगले बॉक्स पर जाता है; तीर और Tab उनके बीच जाते हैं, या वहाँ टाइप करने के लिए किसी बॉक्स पर क्लिक करें। ऋणात्मक संख्याओं के विषम मूल चलते हैं: 3 <sup>x</sup>√y –8 = –2।",
