    "del_or_shift_backspace_2": "[Del या Shift+Backspace] दिखाई गई संख्या और स्थिरांक व लंबित ऑपरेशन साफ़ करने के लिए क्लिक करें।",
    "enter_finishes_any_function": "[ENTER] किसी भी फ़ंक्शन या ऑपरेशन को पूरा करता है और परिणाम दिखाता है।",
    "if_there_any_unfinished": "यदि इस कुंजी के क्लिक या दबने से पहले कोई अधूरे कोष्ठक वाले व्यंजक हैं,",
    "they_get_finished_automaticaly": "तो वे अपने आप पूरे हो जाते हैं। 2*(2+3*(2+4))=40 वही है जो 2*(2+3*(2+4=40 टाइप करना।",
