    "cursor_click_into_equation_2": "कर्सर: समीकरण के बीच को ठीक करने के लिए समीकरण में क्लिक करें, या परिणाम के ऊपर की छोटी पंक्ति पर डबल-क्लिक करें, या तीर कुंजियों का उपयोग करें। जब कर्सर अंदर हो, तो कुंजियाँ कर्सर पर लिखती हैं जैसा समीकरण पढ़ता है:",
    "writes_sin_and": "sin( लिखता है और",
