    "and_3": ", और",
    "removes_what_before_cursor": "कर्सर से पहले की चीज़ हटाता है। अंत में लौटने पर ([→] या [End]), समीकरण फिर निकाला जाता है और कैलकुलेटर हमेशा की तरह आगे चलता है; = उसे कहीं से भी पूरा करता है। परिणाम के बाद, [←] उसका समीकरण फिर दर्ज करता है और [→] कर्सर को उसकी शुरुआत पर रखता है।",
    "d_or_changes_mode": "[d या °] त्रिकोणमितीय फ़ंक्शनों को डिग्री में व्यक्त करने के लिए मोड बदलता है।",
    "d_or_changes_mode_2": "[d या °] त्रिकोणमितीय फ़ंक्शनों को रेडियन में व्यक्त करने के लिए मोड बदलता है।",
    "d_or_changes_mode_3": "[d या °] त्रिकोणमितीय फ़ंक्शनों को ग्रेडियन में व्यक्त करने के लिए मोड बदलता है, पूरे चक्कर के लिए 400 और समकोण के लिए 100: sin 100 है 1। कुंजी Rad से Deg से Grad और वापस Rad पर जाती है, और उस इकाई का नाम बताती है जिस पर वह आगे जाएगी।",
    "f_turns_fraction_mode": "[f] भिन्न मोड चालू और बंद करता है। जब यह चालू हो (डिस्प्ले में FRAC), तो टाइप करते समय हर भाग भिन्न के रूप में बनता है: 1 ÷ 2 + 1 ÷ 3 ½ + ⅓ दिखाता है, और = 5/6 दिखाता है। परिणाम जब भी भिन्न हो सकें भिन्न होते हैं, 10 अंकों तक; जो संख्या भिन्न नहीं है, जैसे π या √2, दशमलव रहती है। कॉपी भिन्न को 5/6 के रूप में देता है। मोड तब तक चालू रहता है जब तक आप फिर क्लिक",
    "again_2": "न करें।",
    "h_f_shows_results": "[h, f] परिणाम डिग्री, मिनट और सेकंड में दिखाता है: sin",
    "0_6_36_52": "0.6 Deg में 36°52′11.63″ है, और 2.75 घंटे 2°45′0″। दशमलव के लिए फिर क्लिक करें; संख्या स्वयं वैसी ही रहती है। कोण को ऐसे दर्ज करने के लिए, उसे पेस्ट करें: 12°30′15″ जैसा लिखा है वैसा दिखता है।",
    "o_goes_on_to": "[o] परिणामों के अगले संकेतन पर जाता है: Normal, Fix (1500.00), Sci (1.50e+3), Eng (1.50e+3, दस की घातें तीन के कदमों में) और फिर Normal। जब कोई चालू हो तो डिस्प्ले FIX 2, SCI 2 या ENG 2 दिखाता है, या स्वतः स्थानों के साथ केवल SCI और ENG: हर परिणाम को जितने अंक चाहिए उतने (1.5e+3), Fix Normal के रूप में। दशमलव स्थान और हज़ार विभाजक विकल्प टैब पर तय होते हैं, जो कुंजी के बाद आता है।",
