    "again_to_return_buttons": "करें।",
    "opens_parenthetical_expression_expressions": "[(] कोष्ठक वाला व्यंजक खोलता है। व्यंजक एक के अंदर एक रखे जा सकते हैं। इस पर क्लिक करने से बटन के चारों ओर एक घेरा आ जाता है, जो बताता है कि कोष्ठक वाला व्यंजक अब भी सक्रिय है (जब तक सारे व्यंजक बंद कोष्ठक या बराबर चिह्न से बंद न हो जाएँ)।",
    "number_right_before_parenthesis": "कोष्ठक से ठीक पहले की संख्या से गुणा होता है: 5 ( 2 + 3 ) है 5 × (2 + 3)।",
    "closes_parenthetical_expression_ring": "[)] कोष्ठक वाला व्यंजक बंद करता है। ( कोष्ठक कुंजी के चारों ओर का घेरा तब तक रहेगा जब तक सारे व्यंजक इस कुंजी से या बराबर चिह्न पर क्लिक करने के बाद बंद न हो जाएँ।",
    "calculates_percentages_adds_markups": "[%] प्रतिशत निकालता है, मार्कअप जोड़ता है, और छूट घटाता है। अकेला यह मान को 100 से भाग देता है: 50 % से 0.5 मिलता है। उदाहरण के लिए, 500 का 8% निकालने के लिए, 8 % × 500 = दर्ज करें, जिससे 40 मिलता है।",
    "to_add_markup_or": "मार्कअप जोड़ने या छूट घटाने के लिए, इसे + या – कुंजी के बाद उपयोग करें। उदाहरण के लिए, 8% बिक्री कर के साथ $500 की वस्तु की कुल लागत निकालने के लिए, 500 + 8 % = दर्ज करें, जिससे 540 मिलता है।",
