    "since_only_few_atoms_4": "क्योंकि रॉन्टजेनियम के केवल कुछ परमाणु ही बने हैं, फ़िलहाल इसका मूलभूत वैज्ञानिक अनुसंधान के बाहर कोई उपयोग नहीं है।",
    "roentgenium_was_first_produced": "रॉन्टजेनियम को पहली बार 1994 के अंत में जर्मनी के डार्मस्टाट स्थित गेज़ेलशाफ़्ट फ़ूअर श्वेरीओनेनफ़ोर्शुंग में पीटर आर्मब्रस्टर, गॉटफ़्रीड मुंज़ेनबर्ग और उनकी टीम ने बनाया।",
    "copernicium": "कोपरनिशियम",
    "since_only_few_atoms_5": "क्योंकि कोपरनिशियम के केवल कुछ परमाणु ही बने हैं, फ़िलहाल इसका मूलभूत वैज्ञानिक अनुसंधान के बाहर कोई उपयोग नहीं है।",
    "copernicium_was_first_produced": "कोपरनिशियम को पहली बार 9 फ़रवरी 1996 को जर्मनी के डार्मस्टाट स्थित गेज़ेलशाफ़्ट फ़ूअर श्वेरीओनेनफ़ोर्शुंग में पीटर आर्मब्रस्टर, गॉटफ़्रीड मुंज़ेनबर्ग और उनकी टीम ने बनाया।",
